  "A class Discord, a five-stack clan, or a creator’s inner circle is still a community, and often better served by a lighter Discord alternative.": "Um Discord da turma da escola, um clã de cinco ou o círculo próximo de um criador ainda são comunidades, e muitas vezes ficam mais bem servidos por uma alternativa mais leve ao Discord.",
