  "A clone copies Discord’s server UI. An alternative solves the same jobs with a different product. Descall is an alternative: servers and calls exist, but the app stays lighter.": "Um clone copia a interface de servidores do Discord. Uma alternativa resolve as mesmas tarefas com outro produto. O Descall é uma alternativa: tem servidores e chamadas, mas o app continua mais leve.",
  "A code was just sent. Wait a minute before requesting another.": "Um código acabou de ser enviado. Espere um minuto antes de pedir outro.",
  "A correct call doubles your bet": "Acertar dobra sua aposta",
  "A direct message with a poll on Descall": "Uma mensagem direta com uma enquete no Descall",
  "A flag you buy stays on your account; change it whenever you like. Only one flag is worn at a time.": "Uma bandeira comprada fica na sua conta; troque quando quiser. Só uma bandeira pode ser usada por vez.",
  "A free Discord alternative with real servers, roles, channels, voice, and templates, plus chat, calls, and": "Uma alternativa gratuita ao Discord com servidores de verdade, cargos, canais, voz e modelos, além de chat, chamadas e",
  "A good Discord replacement matches your real habits. If your habit is “call friends + queue + share screen,” Descall is a direct replacement. If your habit is “run a 10k-member server with 30 bots,” stay on Discord for that job.": "Um bom substituto do Discord combina com os seus hábitos reais. Se o seu hábito é “ligar para os amigos + entrar na fila + compartilhar a tela”, o Descall é um substituto direto. Se o seu hábito é “administrar um servidor de 10 mil membros com 30 bots”, continue no Discord para isso.",
  "A lighter home for friends and squads, real servers, HD calls, screen share, and": "Um lar mais leve para amigos e equipes, com servidores de verdade, chamadas em HD, compartilhamento de tela e",
  "A nebula with a slow drift and a quiet field of stars.": "Uma nebulosa em deriva lenta e um campo tranquilo de estrelas.",
