  "Friend requests, online presence, and quick invites so your squad can jump into chat or voice.": "Pedidos de amizade, presença online e convites rápidos para sua equipe entrar no chat ou na voz.",
  "Friend voice + servers → Descall. Huge community → Discord. Pure voice server → TeamSpeak. Read our compare page before you force a full migration.": "Voz com amigos + servidores → Descall. Comunidade enorme → Discord. Servidor só de voz → TeamSpeak. Leia nossa página de comparação antes de forçar uma migração completa.",
  "Friend-group chat and voice without Nitro friction": "Chat e voz para grupos de amigos sem a chatice do Nitro",
