  "Look for free WebRTC calls, screen share, and a desktop app. Descall is built for that without paywalling talk time.": "Procure chamadas WebRTC grátis, compartilhamento de tela e um app para computador. O Descall foi feito para isso, sem cobrar pelo tempo de conversa.",
