  "Looking for a Discord replacement, not just another bookmark? Descall replaces Discord for the daily loop: DMs, group chat, free voice/video, and screen share, while you keep Discord for the big public servers you still need.": "Procurando um substituto do Discord, e não só mais um favorito no navegador? O Descall substitui o Discord no dia a dia: DMs, chat em grupo, voz/vídeo grátis e compartilhamento de tela, enquanto você mantém o Discord para os grandes servidores públicos de que ainda precisa.",
  "Looking for a voice chat alternative to Discord? How Descall handles free WebRTC calls, server voice, screen share, and gaming nights.": "Procurando uma alternativa de chat de voz ao Discord? Veja como o Descall lida com chamadas WebRTC grátis, voz no servidor, compartilhamento de tela e noites de jogo.",
