  "More options": "Mais opções",
  "More reactions": "Mais reações",
  "Most Discord replacement attempts fail when voice feels worse. Descall invests in WebRTC calls, TURN, and screen-share presets so nightly voice stays easy.": "A maioria das tentativas de substituir o Discord falha quando a voz fica pior. O Descall investe em chamadas WebRTC, TURN e predefinições de compartilhamento de tela para a voz de todas as noites continuar fácil.",
  "Most community platforms either drown you in mega-server chrome or skip structure entirely. Descall gives you real servers with categories, text/voice/stage channels, roles, channel overrides, and ready-made community templates, so a clan, class, or creator circle can launch organized in minutes.": "A maioria das plataformas de comunidade ou afoga você na estrutura de mega-servidor ou deixa a organização de lado. O Descall oferece servidores de verdade com categorias, canais de texto/voz/palco, cargos, permissões por canal e modelos de comunidade prontos, para que um clã, uma turma ou o círculo de um criador comece organizado em minutos.",
  "Most friend groups feel settled within two weeks of moving evening voice.": "A maioria dos grupos de amigos se adapta em até duas semanas depois de levar a voz da noite.",
  "Most groups dual-stack for a month, then realize 90% of pings happen on Descall. That’s a healthy Discord replacement path, no big-bang migration required.": "A maioria dos grupos usa os dois por um mês e depois percebe que 90% das menções acontecem no Descall. Esse é um caminho saudável para substituir o Discord, sem precisar de uma migração radical.",
  "Most groups want both. Descall pairs DMs and servers with the same voice stack so you are not juggling two apps.": "A maioria dos grupos quer os dois. O Descall junta DMs e servidores com a mesma estrutura de voz, para você não se virar com dois apps.",
