  "No. Core chat, servers, and calls are free. DesCoin only buys cosmetics.": "Não. Chat, servidores e chamadas essenciais são grátis. A DesCoin só compra cosméticos.",
  "No. Descall makes the product, and the article states where Discord still wins, bots, giant communities, and broader historic client coverage.": "Não. O Descall faz o produto, e o artigo diz onde o Discord ainda vence: bots, comunidades gigantes e maior cobertura histórica de clientes.",
  "No. Slack, Telegram, and TeamSpeak overlap only on some jobs. Compare by voice, servers, and whether core features are free.": "Não. Slack, Telegram e TeamSpeak só coincidem em algumas tarefas. Compare por voz, servidores e se os recursos essenciais são grátis.",
