  "Passwords are hashed server-side. Google sign-in is available where configured. Keep your credentials private and sign out on shared devices.": "As senhas são protegidas com hash no servidor. O login com Google está disponível onde configurado. Mantenha suas credenciais em sigilo e saia da conta em dispositivos compartilhados.",
