  "People in voice": "Pessoas na voz",
  "People saying “apps like Discord” usually want chat + persistent groups + voice. Some also want screen share. Descall covers that core. It does not try to clone every Discord bot and Stage feature, and that focus is the product.": "Quem procura “apps parecidos com o Discord” geralmente quer chat + grupos permanentes + voz. Alguns também querem compartilhar a tela. O Descall cobre esse essencial. Ele não tenta clonar todos os bots e o recurso de palco do Discord, e esse foco é o produto.",
  "People you may know, ranked by mutual friends and shared groups.": "Pessoas que você talvez conheça, ordenadas por amigos e grupos em comum.",
