  "PiP / minimize-friendly call UX": "Chamadas que funcionam bem em PiP / minimizadas",
  "Pick Descall for nightly friend voice and servers without Nitro. Keep Discord if you still depend on a large bot marketplace or huge public servers.": "Escolha o Descall para voz com amigos todas as noites e servidores sem Nitro. Fique no Discord se você ainda depende de um grande marketplace de bots ou de servidores públicos enormes.",
  "Pick Descall when your group wants a lighter Discord alternative for chat, voice, and screen share. Keep Discord when you still run large public communities and bots.": "Escolha o Descall quando seu grupo quiser uma alternativa mais leve ao Discord para chat, voz e compartilhamento de tela. Fique no Discord quando você ainda administra grandes comunidades públicas e bots.",
  "Pick Gaming, Friends, or Community templates so roles and staff rooms appear ready. Invite codes replace Discord’s invite links.": "Escolha os modelos Jogos, Amigos ou Comunidade para que cargos e salas da equipe já venham prontos. Os códigos de convite substituem os links de convite do Discord.",
