  "Voice, video, and screen share": "Voz, vídeo e compartilhamento de tela",
  "Voice-first classics. Weak for modern chat, presence, and mobile.": "Clássicos focados em voz. Fracos em chat moderno, presença e celular.",
  "Voice/video and screen share for hangouts": "Voz/vídeo e compartilhamento de tela para encontros",
  "Volume": "Volume",
  "Vote first to see who voted.": "Vote primeiro para ver quem votou.",
  "Waiting for others to join…": "Esperando os outros entrarem…",
  "Waiting for screen…": "Esperando a tela…",
  "Waiting for the call…": "Aguardando a chamada…",
  "Waiting…": "Aguardando…",
  "Want a voice chat alternative to Discord without Nitro friction? Descall uses WebRTC voice/video with TURN support, incoming-call UX, PiP, and screen-share quality presets, free for core communication.": "Quer uma alternativa de chat de voz ao Discord sem a fricção do Nitro? O Descall usa voz/vídeo WebRTC com suporte a TURN, uma boa experiência de chamadas recebidas, PiP e predefinições de qualidade do compartilhamento de tela, grátis para a comunicação essencial.",
  "Warn": "Advertir",
  "Warning": "Aviso",
  "Watch list is not migrated yet.": "A lista de observação ainda não foi migrada.",
  "Watching": "Assistindo",
  "Watching something": "Assistindo algo",
  "Watching this flip…": "Assistindo a este cara ou coroa…",
  "Watching this hand…": "Assistindo a esta mão…",
  "Watching this spin…": "Assistindo a este giro…",
  "We are (players already)": "Somos (jogadores já no grupo)",
  "We care about your privacy": "Nos importamos com a sua privacidade",
  "We don’t claim Discord’s bot marketplace, Stage events, or every platform client. Honesty ranks better than doorway pages.": "Não dizemos ter o marketplace de bots do Discord, eventos de palco nem clientes para todas as plataformas. Honestidade rende mais do que páginas de isca.",
  "We focus on real-time messaging, group voice/video, screen share, and a polished desktop experience, without turning private chats into SEO landings.": "Focamos em mensagens em tempo real, voz/vídeo em grupo, compartilhamento de tela e uma experiência caprichada no computador, sem transformar chats privados em páginas de SEO.",
  "We got your note. We’ll reply at the email you gave.": "Recebemos sua mensagem. Vamos responder no e-mail que você informou.",
  "We now ask everyone for their date of birth so we can keep Descall safe and show the right features for your age.": "Agora pedimos a data de nascimento de todos para manter o Descall seguro e mostrar os recursos certos para sua idade.",
  "We only use essential cookies; we ask for your permission for analytics.": "Só usamos cookies essenciais; pedimos sua permissão para análises.",
  "We only use the cookies Descall needs to run. We ask for your permission for analytics cookies.": "Só usamos os cookies de que o Descall precisa para funcionar. Pedimos sua permissão para os cookies de análise.",
  "We review every submission and use it to make Descall better.": "Analisamos cada envio e usamos isso para melhorar o Descall.",
  "We scored apps on free core chat/calls, voice quality path, server tools, desktop/mobile reality, and whether friend groups can switch in a week, not on who has the longest feature checklist.": "Avaliamos os apps por chat/chamadas essenciais grátis, caminho para qualidade de voz, ferramentas de servidor, realidade no computador/celular e se grupos de amigos conseguem mudar em uma semana, não por quem tem a maior lista de recursos.",
  "We sent a 6-digit code to your email.": "Enviamos um código de 6 dígitos para o seu e-mail.",
  "We use infrastructure providers (hosting, database, authentication) as processors. Content you send is visible to the recipients you choose (DMs, groups).": "Usamos provedores de infraestrutura (hospedagem, banco de dados, autenticação) como operadores. O conteúdo que você envia fica visível para os destinatários que você escolher (DMs, grupos).",
  "We use this data to provide chat and calls, keep the service secure, improve reliability, and communicate important product updates. We do not sell your personal information.": "Usamos esses dados para oferecer chat e chamadas, manter o serviço seguro, melhorar a confiabilidade e comunicar atualizações importantes do produto. Não vendemos suas informações pessoais.",
  "We'll send a code to this email to verify it. It keeps your account safe: recovery, sign-in codes and two-factor authentication.": "Vamos enviar um código para este e-mail para verificá-lo. Isso mantém sua conta segura: recuperação, códigos de login e autenticação de dois fatores.",
  "Weak": "Fraca",
  "Weak connection": "Conexão fraca",
  "Wear": "Usar",
  "Wear it right after buying": "Usar logo depois de comprar",
  "Web + Windows + Android so members can join anywhere": "Web + Windows + Android para os membros entrarem de qualquer lugar",
  "Web / desktop / mobile FCM": "FCM para web / computador / celular",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established.": "O tráfego da web e da API usa HTTPS/TLS. A mídia em tempo real usa WebRTC com DTLS/SRTP entre os participantes quando uma chamada é estabelecida.",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established. Descall does not claim default end-to-end encryption for all message history stored on the server, messages are encrypted in transit and stored so your devices can load chat history.": "O tráfego da web e da API usa HTTPS/TLS. A mídia em tempo real usa WebRTC com DTLS/SRTP entre os participantes quando uma chamada é estabelecida. O Descall não afirma ter criptografia de ponta a ponta por padrão para todo o histórico de mensagens armazenado no servidor; as mensagens são criptografadas em trânsito e armazenadas para que seus dispositivos possam carregar o histórico do chat.",
  "Web app": "App web",
  "WebRTC": "WebRTC",
  "WebRTC voice for DMs, groups, and server lobbies with noise controls when you need them.": "Voz WebRTC para DMs, grupos e lobbies de servidor, com controles de ruído quando você precisar.",
  "WebRTC voice/video with TURN support, incoming call UX, PiP, and screen-share quality controls. A lighter Discord alternative when you want clean calls inside servers or DMs.": "Voz/vídeo WebRTC com suporte a TURN, boa experiência de chamadas recebidas, PiP e controles de qualidade do compartilhamento de tela. Uma alternativa mais leve ao Discord quando você quer chamadas limpas em servidores ou DMs.",
  "Websites like Discord": "Sites como o Discord",
  "Websites like Discord vs installable apps": "Sites como o Discord vs apps instaláveis",
  "Week 1: create a Descall group and move evening voice. Week 2: move media sharing and your gaming server if you play together. Most friend groups don’t need a full export, they need a new habit.": "Semana 1: crie um grupo no Descall e leve a voz da noite. Semana 2: leve o compartilhamento de mídia e seu servidor de jogos, se vocês jogam juntos. A maioria dos grupos de amigos não precisa de uma exportação completa, precisa de um novo hábito.",
  "Week 1: create a Descall group, move evening voice. Week 2: move your server and screen-share sessions. Keep Discord for public servers you still enjoy.": "Semana 1: crie um grupo no Descall e leve a voz da noite. Semana 2: leve seu servidor e as sessões de compartilhamento de tela. Mantenha o Discord para os servidores públicos de que você ainda gosta.",
