  "Windows users should install the desktop client for fewer browser tab mishaps. Android and web cover the rest of the group.": "Quem usa Windows deve instalar o cliente para computador e evitar confusões com abas do navegador. Android e web cobrem o resto do grupo.",
  "Won": "Ganhou",
  "Work-first chat. Huddles exist, but gamers looking for a Discord alternative usually want evenings, not tickets.": "Chat focado em trabalho. Existem os huddles, mas gamers procurando uma alternativa ao Discord geralmente querem noites de jogo, não tickets.",
