  "Write your announcement content...": "Escreva o conteúdo do seu aviso...",
  "Write your must-haves (voice, servers, mobile). Trial with your real friends for seven nights. Keep the app that gets used without reminders.": "Anote o que é indispensável (voz, servidores, celular). Teste com seus amigos de verdade por sete noites. Fique com o app que é usado sem precisar de lembrete.",
